with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الأرصاد الطبية والصحة المناخية والبيئية','الأرصاد الحيوية ومؤشرات الراحة الحرارية والصحة المناخية وجودة الهواء والغبار والدخان والإنذار المبكر الصحي.',41,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الطقس والصحة العامة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'جودة الهواء والمخاطر البيئية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('biometeorology-foundations','مقدمة في الأرصاد الحيوية والطبية','تفاعل الظروف الجوية مع جسم الإنسان والصحة.','{"blocks":[{"type":"text","text":"يتناول الدرس مقدمة في الأرصاد الحيوية والطبية ضمن تقاطع الأرصاد الجوية والبيئة والصحة العامة."},{"type":"text","text":"المبدأ: تفاعل الظروف الجوية مع جسم الإنسان والصحة.، ويجب التمييز بين المؤشر الجوي والنتيجة الصحية التي تتأثر بعوامل متعددة."},{"type":"text","text":"تحدد الظاهرة الجوية والفترة والمجال المكاني والفئات أو المرافق المستهدفة وفق البيانات المتاحة."},{"type":"text","text":"تجمع بيانات المحطات الجوية ومحطات جودة الهواء والمنتجات الفضائية والسجلات البيئية ذات الصلة."},{"type":"text","text":"تراجع جودة القياسات وتواترها وتغطيتها المكانية وتوقيت تجميعها قبل الربط والتحليل."},{"type":"text","text":"تفسر العلاقة بين الطقس والتعرض مع مراعاة العوامل الاجتماعية والسلوكية والبيئية الأخرى."},{"type":"text","text":"تستخدم المؤشرات المعتمدة والعتبات المحلية، ولا تستبدل المعايير الصحية الرسمية بتقديرات غير موثقة."},{"type":"text","text":"تحلل الأنماط الزمنية والمكانية وتحدد مواسم الذروة والفجوات في الرصد."},{"type":"text","text":"تحمى البيانات الشخصية والحساسة، وتستخدم البيانات المجمعة أو المجهولة عند الحاجة."},{"type":"text","text":"ينسق إعداد الرسائل مع الجهات الصحية والبيئية المختصة لتجنب التفسير الطبي غير الملائم."},{"type":"text","text":"مثال تطبيقي: إعداد لوحة متابعة تربط توقع الحرارة أو الجسيمات بمناطق التعرض وتعرض مستوى الثقة ومصدر البيانات."},{"type":"callout","text":"الخلاصة: الخدمة الجوية الصحية تقدم مؤشرات مساعدة للجهات المختصة ولا تحل محل التقييم أو القرار الطبي."}]}',4560,55,'["تحديد المتغيرات الجوية والبيئية المؤثرة","تحليل التعرض والأنماط المكانية والزمنية","إعداد معلومات منسقة مع الجهات المختصة"]','الطقس والصحة العامة'),
('thermal-comfort-indices','مؤشرات الراحة الحرارية للإنسان','دمج الحرارة والرطوبة والرياح والإشعاع.','{"blocks":[{"type":"text","text":"يتناول الدرس مؤشرات الراحة الحرارية للإنسان ضمن تقاطع الأرصاد الجوية والبيئة والصحة العامة."},{"type":"text","text":"المبدأ: دمج الحرارة والرطوبة والرياح والإشعاع.، ويجب التمييز بين المؤشر الجوي والنتيجة الصحية التي تتأثر بعوامل متعددة."},{"type":"text","text":"تحدد الظاهرة الجوية والفترة والمجال المكاني والفئات أو المرافق المستهدفة وفق البيانات المتاحة."},{"type":"text","text":"تجمع بيانات المحطات الجوية ومحطات جودة الهواء والمنتجات الفضائية والسجلات البيئية ذات الصلة."},{"type":"text","text":"تراجع جودة القياسات وتواترها وتغطيتها المكانية وتوقيت تجميعها قبل الربط والتحليل."},{"type":"text","text":"تفسر العلاقة بين الطقس والتعرض مع مراعاة العوامل الاجتماعية والسلوكية والبيئية الأخرى."},{"type":"text","text":"تستخدم المؤشرات المعتمدة والعتبات المحلية، ولا تستبدل المعايير الصحية الرسمية بتقديرات غير موثقة."},{"type":"text","text":"تحلل الأنماط الزمنية والمكانية وتحدد مواسم الذروة والفجوات في الرصد."},{"type":"text","text":"تحمى البيانات الشخصية والحساسة، وتستخدم البيانات المجمعة أو المجهولة عند الحاجة."},{"type":"text","text":"ينسق إعداد الرسائل مع الجهات الصحية والبيئية المختصة لتجنب التفسير الطبي غير الملائم."},{"type":"text","text":"مثال تطبيقي: إعداد لوحة متابعة تربط توقع الحرارة أو الجسيمات بمناطق التعرض وتعرض مستوى الثقة ومصدر البيانات."},{"type":"callout","text":"الخلاصة: الخدمة الجوية الصحية تقدم مؤشرات مساعدة للجهات المختصة ولا تحل محل التقييم أو القرار الطبي."}]}',4570,55,'["تحديد المتغيرات الجوية والبيئية المؤثرة","تحليل التعرض والأنماط المكانية والزمنية","إعداد معلومات منسقة مع الجهات المختصة"]','الطقس والصحة العامة'),
('heat-health-climate-services','الخدمات المناخية لمخاطر الحر الصحية','توقع موجات الحر وربطها بالمعلومات الصحية.','{"blocks":[{"type":"text","text":"يتناول الدرس الخدمات المناخية لمخاطر الحر الصحية ضمن تقاطع الأرصاد الجوية والبيئة والصحة العامة."},{"type":"text","text":"المبدأ: توقع موجات الحر وربطها بالمعلومات الصحية.، ويجب التمييز بين المؤشر الجوي والنتيجة الصحية التي تتأثر بعوامل متعددة."},{"type":"text","text":"تحدد الظاهرة الجوية والفترة والمجال المكاني والفئات أو المرافق المستهدفة وفق البيانات المتاحة."},{"type":"text","text":"تجمع بيانات المحطات الجوية ومحطات جودة الهواء والمنتجات الفضائية والسجلات البيئية ذات الصلة."},{"type":"text","text":"تراجع جودة القياسات وتواترها وتغطيتها المكانية وتوقيت تجميعها قبل الربط والتحليل."},{"type":"text","text":"تفسر العلاقة بين الطقس والتعرض مع مراعاة العوامل الاجتماعية والسلوكية والبيئية الأخرى."},{"type":"text","text":"تستخدم المؤشرات المعتمدة والعتبات المحلية، ولا تستبدل المعايير الصحية الرسمية بتقديرات غير موثقة."},{"type":"text","text":"تحلل الأنماط الزمنية والمكانية وتحدد مواسم الذروة والفجوات في الرصد."},{"type":"text","text":"تحمى البيانات الشخصية والحساسة، وتستخدم البيانات المجمعة أو المجهولة عند الحاجة."},{"type":"text","text":"ينسق إعداد الرسائل مع الجهات الصحية والبيئية المختصة لتجنب التفسير الطبي غير الملائم."},{"type":"text","text":"مثال تطبيقي: إعداد لوحة متابعة تربط توقع الحرارة أو الجسيمات بمناطق التعرض وتعرض مستوى الثقة ومصدر البيانات."},{"type":"callout","text":"الخلاصة: الخدمة الجوية الصحية تقدم مؤشرات مساعدة للجهات المختصة ولا تحل محل التقييم أو القرار الطبي."}]}',4580,55,'["تحديد المتغيرات الجوية والبيئية المؤثرة","تحليل التعرض والأنماط المكانية والزمنية","إعداد معلومات منسقة مع الجهات المختصة"]','الطقس والصحة العامة'),
